#news-container { background-color:#f4f2f0;}
.news-txt h2 { color:#002d49; font-weight:bold; text-align:center;}
.news-h2 { color:#008ecf; font-weight:bold;}
.news-h3 { color:#008ecf; font-weight:bold; font-style:italic;}
.news-h4 { color:#1eb9ee; font-weight:bold; font-style:italic;}
.news-line { padding:10px 5px 20px 5px; border-bottom:3px solid #008ecf;}
.news-line2 { padding:10px 5px 20px 5px; border-bottom:3px dotted #008ecf;}
.news-title { color:#008ecf; font-size:20px; font-weight:bold; font-style:italic; padding:20px 5px;}
.news-title-img { float:left; display:block;}
.news-title-txt { float:left; display:block;}
.news-content { margin-left:10%; padding:20px; background:#e2dddb; font-size:15px;}
.news-content .table > thead > tr > th, .news-content .table > tbody > tr > th, .news-content .table > tfoot > tr > th, .news-content .table > thead > tr > td, .news-content .table > tbody > tr > td, .news-content .table > tfoot > tr > td { border-top: 1px solid #000;}
.news-content .table>thead>tr>th { border-bottom: 2px solid #000;}
.page_spacing { padding-top:50px; padding-bottom:50px;}
.page_spacing-2 { padding-top:30px; padding-bottom:30px;}
.page_spacing-3 { padding-top:20px; padding-bottom:20px;}
.news-item { padding:30px 0 0 0;}
.news-item-more { border-bottom:2px solid #53c7ee; padding:5px 0 5px 0;}
.news-time-style-1 { color:#666; font-size:18px; font-style:italic;}
.news-img-border { border-bottom:8px solid #0086cd;}
.news-title-style { padding:0 0 0 0; color:#0088d1; font-weight:bold; font-size:18px; word-wrap: break-word; word-break: break-all;}
.news-text{ font-size:16px;}
.news-right-list { padding:30px 0 30px 0;}
.news-right-list-title { color:#0088d1; font-weight:bold; font-size:18px; font-style:italic;}
